            var atkBpp = handle.GetBppByAISide(atkSide);
            var defBpp = handle.GetBppByAISide(defSide);
            if (atkBpp == null || defBpp == null)
                return CELL_FALSE;

            byte count = atkBpp.WAZA_GetCount();
            for (byte i = 0; i < count; i++)
            {
                var aff = handle.GetBattleSimulator().CalcTypeAffinity(atkBpp.GetID(), defBpp.GetID(), atkBpp.WAZA_GetID(i), false);
                if (aff > TypeAffinity.AffinityID.TYPEAFF_1)
                    return CELL_TRUE;
            }
            return CELL_FALSE;
        }
		private static long CMDFUNC_IF_LAST_WAZA_DAMAGE_CHECK(global::Dpr.Battle.Logic.AiScriptCommandHandler handle, long[] args) {
            var atkBpp = handle.GetAttackPokeParam();
            var defBpp = handle.GetDefensePokeParam();

            if (atkBpp == null || defBpp == null)
                return CELL_FALSE;

            var bpp = handle.GetBppByAISide((uint)args[0]);
            bool loss_flag = args[1] != 0;

            uint maxDamage = handle.CalcMaxDamage(atkBpp, defBpp, loss_flag);
            ushort lastDamage = handle.GetBattleSimulator().CalcDamage(bpp.GetID(), defBpp.GetID(), bpp.GetPrevWazaID(), true, loss_flag);

            return (maxDamage < lastDamage) ? CELL_TRUE : CELL_FALSE;
        }
		private static long CMDFUNC_CHECK_STATUS_UP(global::Dpr.Battle.Logic.AiScriptCommandHandler handle, long[] args) {
            var bpp = handle.GetBppByAISide((uint)args[0]);

            // InitializeArray @ global-metadata.dat 0x666830 = {1, 2, 3, 4, 5, 6, 7}.
            var rankIDs = new BTL_POKEPARAM.ValueID[]
            {
                BTL_POKEPARAM.ValueID.BPP_ATTACK_RANK, BTL_POKEPARAM.ValueID.BPP_DEFENCE_RANK, BTL_POKEPARAM.ValueID.BPP_SP_ATTACK_RANK,
                BTL_POKEPARAM.ValueID.BPP_SP_DEFENCE_RANK, BTL_POKEPARAM.ValueID.BPP_AGILITY_RANK, BTL_POKEPARAM.ValueID.BPP_HIT_RATIO,
                BTL_POKEPARAM.ValueID.BPP_AVOID_RATIO,
            };

            int total = 0;
            for (int i = 0; i < rankIDs.Length; i++)
            {
                int rank = bpp.GetValue(rankIDs[i]);
                total += (rank > BTL_POKEPARAM.RANK_STATUS_DEFAULT) ? rank - BTL_POKEPARAM.RANK_STATUS_DEFAULT : 0;
            }

            return total;
        }
		private static long CMDFUNC_CHECK_STATUS_DIFF(global::Dpr.Battle.Logic.AiScriptCommandHandler handle, long[] args) {
