		private static long CMDFUNC_COMP_POWER_WITH_PARTNER(global::Dpr.Battle.Logic.AiScriptCommandHandler handle, long[] args) {
            var atkBpp = handle.GetAttackPokeParam();
            var defBpp = handle.GetDefensePokeParam();

            if (atkBpp == null || defBpp == null)
                return (long)AICompPower.COMP_POWER_NONE;

            bool loss_flag = args[0] != 0;
            ushort currentDamage = handle.GetBattleSimulator().CalcDamage(atkBpp.GetID(), defBpp.GetID(), handle.GetCurrentWazaNo(), true, loss_flag);

            var clientID = handle.GetMainModule().BtlPosToClientID(handle.GetAttackPokePos());
            var party = handle.GetPokeCon().GetPartyDataConst(clientID);
            int myIndex = party.FindMember(atkBpp);

            if (currentDamage == 0 || myIndex < 0)
                return (long)AICompPower.COMP_POWER_NONE;

            var frontCount = handle.GetMainModule().GetClientFrontPosCount(clientID);
            for (int i = 0; i < frontCount; i++)
            {
                var bpp = party.GetMemberDataConst((byte)i);
                if (!bpp.IsFightEnable())
                    continue;

                if (i == myIndex)
                {
                    for (byte j = 0; j < bpp.WAZA_GetCount(); j++)
                    {
                        if (j == handle.GetCurrentWazaIndex())
                            continue;

                        if (handle.GetBattleSimulator().CalcDamage(bpp.GetID(), defBpp.GetID(), bpp.WAZA_GetID(j), true, loss_flag) > currentDamage)
                            return (long)AICompPower.COMP_POWER_NOTOP;
                    }
                }
                else
                {
                    for (byte j = 0; j < bpp.WAZA_GetCount(); j++)
                    {
                        if (handle.GetBattleSimulator().CalcDamage(bpp.GetID(), defBpp.GetID(), bpp.WAZA_GetID(j), true, loss_flag) > currentDamage)
                            return (long)AICompPower.COMP_POWER_NOTOP;
                    }
                }
            }

            return (long)AICompPower.COMP_POWER_TOP;
        }
