		private static long CMDFUNC_GET_MAX_WAZA_POWER_INCLUDE_AFFINITY(global::Dpr.Battle.Logic.AiScriptCommandHandler handle, long[] args) {
            var attackPoke = handle.GetBppByAISide((uint)args[0]);
            var defensePoke = handle.GetBppByAISide((uint)AIStatusFlag.CHECK_DEFENCE);
            var defenseFriendPoke = handle.GetBppByAISide((uint)AIStatusFlag.CHECK_DEFENCE_FRIEND);

            uint maxPower = GetMaxWazaPowerIncludeAffinity(handle.GetBattleEnv(), handle.GetBattleSimulator(), attackPoke, defensePoke);
            if (defensePoke != defenseFriendPoke)
            {
                uint friendPower = GetMaxWazaPowerIncludeAffinity(handle.GetBattleEnv(), handle.GetBattleSimulator(), attackPoke, defenseFriendPoke);
                if (maxPower < friendPower)
                    maxPower = friendPower;
            }

            // 01ff23f8: `sxtw` — the uint result is returned sign-extended through int.
            return (int)maxPower;
        }
		private static uint GetMaxWazaPowerIncludeAffinity(in global::Dpr.Battle.Logic.BattleEnv battleEnv, global::Dpr.Battle.Logic.BattleSimulator pSimulator, global::Dpr.Battle.Logic.BTL_POKEPARAM attackPoke, global::Dpr.Battle.Logic.BTL_POKEPARAM defensePoke) {
            uint maxPower = 0;
            byte wazaCount = attackPoke.WAZA_GetCount();

            for (byte i = 0; i < wazaCount; i++)
            {
                if (attackPoke.WAZA_GetPP(i) == 0)
                    continue;

                var wazano = attackPoke.WAZA_GetID(i);
                if (!WAZADATA.IsDamage(wazano))
                    continue;

                uint power = WAZADATA.GetPower(wazano);
                var aff = pSimulator.CalcTypeAffinity(attackPoke.GetID(), defensePoke.GetID(), wazano, false);
                uint affPower = calc.AffDamage(power, aff);
                if (maxPower < affPower)
                    maxPower = affPower;
            }

            return maxPower;
        }
