            var recorder = handle.GetBattleEnv().GetActionRecorder();

            if (recorder.CheckAction(pokeId, 0, ActionRecorder.ActionID.FAILED_HIT_PERCENTAGE) ||
                recorder.CheckAction(pokeId, 0, ActionRecorder.ActionID.FAILED_TOKUSEI))
                return CELL_TRUE;

            return recorder.CheckAction(pokeId, 0, ActionRecorder.ActionID.FAILED_TYPE) ? CELL_TRUE : CELL_FALSE;
        }
